const CACHE='chemistry-atlas-analytical-electrochem-v4';
const SHELL=['import-lessons.css','chapter-9.html','chapter-10.html','assets/ch09/addition.webp','assets/ch09/detection.webp','assets/ch09/external.webp','assets/ch09/precision.webp','assets/ch09/qcm-response.webp','assets/ch09/qcm-structure.webp','assets/ch09/range.webp','assets/ch09/sauerbrey.webp','assets/ch10/cells.webp','assets/ch10/equilibrium.webp','assets/ch10/mixture-balance.webp','assets/ch10/mixture-potential.webp','assets/ch10/nernst.webp','assets/ch10/notation.webp','assets/ch10/salt-bridge.webp','assets/ch10/she.webp','fractions.css','./','index.html','chapter-1.html','chapter-2.html','chapter-3.html','chapter-4.html','chapter-5.html','chapter-6.html','chapter-7.html','chapter-8.html','redox.css','topic-formulas.html','terms.html','term.html','style.css','content.css','lesson.css','course-extra.css','ppt-figures.css','topic-formulas.css','script.js','icon.svg','manifest.webmanifest','data/terms.json','data/notes.json','electroanalysis.css','chapter-11.html','chapter-12.html','chapter-13.html','chapter-14.html','assets/ch11/glass-membrane.webp','assets/ch11/valinomycin.webp','assets/ch12/cyclic-peaks.webp','assets/ch12/stripping.webp','assets/ch12/three-electrode.webp','assets/ch13/bulk-decay.webp','assets/ch13/cerium-cycle.webp','assets/ch14/glucose-electrode.webp','assets/ch14/mediator-cycle.webp','assets/ch14/microfabricated.webp'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{
  if(event.request.method!=='GET'||new URL(event.request.url).origin!==location.origin)return;
  event.respondWith((async()=>{const cached=await caches.match(event.request);try{const response=await fetch(event.request);if(response.ok){const cache=await caches.open(CACHE);await cache.put(event.request,response.clone())}return response}catch{if(cached)return cached;if(event.request.mode==='navigate')return (await caches.match('index.html'))||new Response('<h1>暂时离线</h1><p>联网访问一次后即可离线阅读已缓存内容。</p>',{status:503,headers:{'Content-Type':'text/html; charset=utf-8'}});return new Response('',{status:503,statusText:'Offline'})}})());
});
